<body>
  <main class="page-shell">
    <section class="hero" aria-label="Support page introduction">
      <div>
        <span class="eyebrow">Support team</span>
        <h1>Get help from our product specialists.</h1>
      </div>
      <p>
        Send us the details below and our support team will follow up with the right next steps for your request.
      </p>
      <ul class="hero-highlights">
        <li>
          <strong>Fast follow-up</strong>
          We review new support requests quickly during standard business hours.
        </li>
        <li>
          <strong>Clear communication</strong>
          Include your contact details so we can reach you on the channel that works best.
        </li>
      </ul>
    </section>

    <section class="form-card" aria-label="Support contact form">
      <h2>Contact support</h2>
      <p>All fields marked as required must be completed before submitting.</p>

      <form id="support-form" novalidate>
        <div class="form-field">
          <label for="full-name">Full name *</label>
          <input
            id="full-name"
            name="fullName"
            type="text"
            autocomplete="name"
            placeholder="Jordan Lee"
            required
            aria-describedby="full-name-error"
          >
          <p class="error-message" id="full-name-error" aria-live="polite"></p>
        </div>

        <div class="form-field">
          <label for="email-address">Email address *</label>
          <input
            id="email-address"
            name="email"
            type="email"
            autocomplete="email"
            placeholder="jordan@example.com"
            required
            aria-describedby="email-address-error"
          >
          <p class="error-message" id="email-address-error" aria-live="polite"></p>
        </div>

        <div class="form-field">
          <label for="phone-number">Phone number</label>
          <input
            id="phone-number"
            name="phone"
            type="tel"
            autocomplete="tel"
            inputmode="tel"
            placeholder="(555) 123-4567"
            aria-describedby="phone-helper phone-number-error"
          >
          <p class="helper-text" id="phone-helper">Optional. Use a number such as (555) 123-4567 or +1 555 123 4567.</p>
          <p class="error-message" id="phone-number-error" aria-live="polite"></p>
        </div>

        <button type="submit">Submit request</button>
        <p class="success-message" id="success-message" aria-live="polite"></p>
      </form>
    </section>
  </main>

  <script>
    const form = document.getElementById("support-form");
    const successMessage = document.getElementById("success-message");
    const phonePattern = /^\+?[0-9()\-\s]{7,20}$/;

    const fieldConfig = {
      fullName: {
        input: document.getElementById("full-name"),
        error: document.getElementById("full-name-error"),
        validate(value) {
          if (!value.trim()) {
            return "Enter your full name.";
          }
          if (value.trim().length < 2) {
            return "Enter a valid full name.";
          }
          return "";
        }
      },
      email: {
        input: document.getElementById("email-address"),
        error: document.getElementById("email-address-error"),
        validate(value) {
          const trimmedValue = value.trim();
          if (!trimmedValue) {
            return "Enter your email address.";
          }
          if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(trimmedValue)) {
            return "Enter a valid email address.";
          }
          return "";
        }
      },
      phone: {
        input: document.getElementById("phone-number"),
        error: document.getElementById("phone-number-error"),
        validate(value) {
          const trimmedValue = value.trim();
          if (!trimmedValue) {
            return "";
          }
          if (!phonePattern.test(trimmedValue)) {
            return "Enter a valid phone number using the expected format.";
          }
          return "";
        }
      }
    };

    function updateAccessibilityState(field, message) {
      const fieldWrapper = field.input.closest(".form-field");
      const describedBy = field.input.getAttribute("aria-describedby") || "";
      const tokens = describedBy.split(/\s+/).filter(Boolean).filter((token) => token !== field.error.id);
      const errorId = field.error.id;

      field.error.textContent = message;
      fieldWrapper.classList.toggle("invalid", Boolean(message));
      field.input.setAttribute("aria-invalid", message ? "true" : "false");

      if (message && !tokens.includes(errorId)) {
        tokens.push(errorId);
      }

      field.input.setAttribute("aria-describedby", tokens.join(" "));
    }

    function setFieldState(fieldName) {
      const field = fieldConfig[fieldName];
      const message = field.validate(field.input.value);
      updateAccessibilityState(field, message);
      return !message;
    }

    function clearFieldState(fieldName) {
      updateAccessibilityState(fieldConfig[fieldName], "");
    }

    Object.keys(fieldConfig).forEach((fieldName) => {
      const { input } = fieldConfig[fieldName];
      input.addEventListener("blur", () => {
        setFieldState(fieldName);
      });
      input.addEventListener("input", () => {
        if (input.closest(".form-field").classList.contains("invalid")) {
          setFieldState(fieldName);
        }
      });
    });

    form.addEventListener("submit", (event) => {
      event.preventDefault();
      successMessage.textContent = "";

      const isValid = Object.keys(fieldConfig)
        .map((fieldName) => setFieldState(fieldName))
        .every(Boolean);

      if (!isValid) {
        const firstInvalidField = Object.values(fieldConfig).find(({ input }) =>
          input.closest(".form-field").classList.contains("invalid")
        );

        if (firstInvalidField) {
          firstInvalidField.input.focus();
        }
        return;
      }

      successMessage.textContent = "Your support request has been submitted.";
      form.reset();
      Object.keys(fieldConfig).forEach((fieldName) => clearFieldState(fieldName));
    });
  </script>
</body>
</html>
